// @file: Independent REL-18 pack-integrity checker. Derives the immutable source corpus from Git,
//   reconstructs the exact command matrix, and checks every committed raw log and generated byte.
// @spec: AI-SKILLS
// @consumers: package.json "release:evidence-pack:check"; release reviewer; contract tests

import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { existsSync, lstatSync, readFileSync } from 'node:fs';
import { basename, isAbsolute, relative, resolve, sep } from 'node:path';
import {
  migrationScopeIdentityFinding,
  releaseEvidenceCommandPlan,
  renderReleaseEvidenceReadme,
  validateReleaseEvidenceResult,
  type ReleaseEvidenceManifest,
} from './release-evidence-contract.ts';

const PROJECT_ROOT = resolve(import.meta.dirname, '../../..');
const PACK_ROOT = resolve(PROJECT_ROOT, 'ai/flow-eval/.baseline/rc-evidence-pack');
const FULL_SHA = /^[0-9a-f]{40}$/;

function codePointCompare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function sha256(bytes: Buffer): string {
  return createHash('sha256').update(bytes).digest('hex');
}

function git(root: string, args: readonly string[]): { status: number | null; output: string } {
  const result = spawnSync('git', args, {
    cwd: root,
    encoding: 'utf8',
    maxBuffer: 4 * 1024 * 1024,
  });
  return { status: result.status, output: `${result.stdout ?? ''}${result.stderr ?? ''}` };
}

function sourceScopes(root: string, sourceCommit: string, failures: string[]): string[] {
  if (!FULL_SHA.test(sourceCommit)) {
    failures.push('sourceCommit не full SHA');
    return [];
  }
  const object = git(root, ['cat-file', '-e', `${sourceCommit}^{commit}`]);
  if (object.status !== 0) {
    failures.push(
      `sourceCommit недоступен как commit (возможно shallow/missing object): ${object.output}`
    );
    return [];
  }
  const ancestry = git(root, ['merge-base', '--is-ancestor', sourceCommit, 'HEAD']);
  if (ancestry.status !== 0) {
    failures.push('sourceCommit не является ancestor текущего HEAD');
    return [];
  }
  const tree = git(root, ['ls-tree', '-d', '--name-only', `${sourceCommit}:migration`]);
  if (tree.status !== 0) {
    failures.push(`migration tree недоступен в sourceCommit: ${tree.output}`);
    return [];
  }
  const scopes = tree.output
    .split(/\r?\n/u)
    .map((line) => line.trim())
    .filter(Boolean)
    .sort(codePointCompare);
  if (scopes.length === 0) failures.push('sourceCommit не содержит migration scope directories');
  if (new Set(scopes).size !== scopes.length) failures.push('source migration scopes не уникальны');
  return scopes;
}

function isContainedFile(packRoot: string, path: string): boolean {
  const contained = relative(packRoot, path);
  return (
    contained.length > 0 &&
    contained !== '..' &&
    !contained.startsWith(`..${sep}`) &&
    !isAbsolute(contained) &&
    existsSync(path) &&
    lstatSync(path).isFile()
  );
}

function checkReleaseEvidencePack(projectRoot: string, packRoot: string): string[] {
  const manifestPath = resolve(packRoot, 'manifest.json');
  if (!existsSync(manifestPath)) return [`pack отсутствует: ${manifestPath}`];

  let manifest: ReleaseEvidenceManifest;
  try {
    manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as ReleaseEvidenceManifest;
  } catch (error) {
    return [`manifest JSON не читается: ${error instanceof Error ? error.message : String(error)}`];
  }

  const failures: string[] = [];
  if (manifest.schema !== 'gennady.rc-evidence-pack.v1') failures.push('неизвестная schema');
  if (!manifest.cleanBefore || !manifest.cleanAfter)
    failures.push('clean-before/after не доказаны');
  if (manifest.migration?.rounds !== 2 || !manifest.migration?.allNoOp) {
    failures.push('migration summary не подтверждает два no-op round');
  }

  const scopes = sourceScopes(projectRoot, manifest.sourceCommit, failures);
  const claimedScopes = Array.isArray(manifest.migration?.scopes)
    ? manifest.migration.scopes.filter((scope): scope is string => typeof scope === 'string')
    : [];
  if (claimedScopes.length !== manifest.migration?.scopes?.length) {
    failures.push('manifest migration scopes содержат нестроковое значение');
  }
  if (scopes.length > 0) {
    const scopeFinding = migrationScopeIdentityFinding(claimedScopes, scopes);
    if (scopeFinding) failures.push(scopeFinding);
  }

  const plan = releaseEvidenceCommandPlan(scopes);
  const commands = Array.isArray(manifest.commands) ? manifest.commands : [];
  if (commands.length !== plan.length) {
    failures.push(`command count: expected ${plan.length}, got ${commands.length}`);
  }
  for (let i = 0; i < plan.length; i++) {
    const expected = plan[i];
    const actual = commands[i];
    if (!actual) continue;
    const expectedText = [expected.command, ...expected.args].join(' ');
    const expectedLog = `logs/${expected.id}.log`;
    if (
      actual.id !== expected.id ||
      actual.command !== expectedText ||
      actual.logFile !== expectedLog
    ) {
      failures.push(`command[${i}] не совпадает с contract: ${actual.id}`);
      continue;
    }
    const logPath = resolve(packRoot, actual.logFile);
    if (!isContainedFile(packRoot, logPath)) {
      failures.push(`${actual.id}: raw log отсутствует, не regular file или вне pack`);
      continue;
    }
    const bytes = readFileSync(logPath);
    if (sha256(bytes) !== actual.sha256) failures.push(`${actual.id}: SHA-256 не совпадает`);
    const verdict = validateReleaseEvidenceResult(
      expected,
      actual.exitCode,
      bytes.toString('utf8')
    );
    if (verdict) failures.push(verdict);
  }

  const readmePath = resolve(packRoot, 'README.md');
  if (!isContainedFile(packRoot, readmePath)) {
    failures.push('generated README отсутствует или не regular file');
  } else {
    try {
      if (readFileSync(readmePath, 'utf8') !== renderReleaseEvidenceReadme(manifest)) {
        failures.push('generated README bytes не совпадают с manifest/renderer');
      }
    } catch (error) {
      failures.push(
        `generated README нельзя реконструировать: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }

  return failures;
}

function main(): void {
  const failures = checkReleaseEvidencePack(PROJECT_ROOT, PACK_ROOT);
  if (failures.length > 0) {
    console.error('[release-evidence-pack-check] FAIL');
    for (const failure of failures) console.error(`- ${failure}`);
    process.exit(1);
  }
  const manifest = JSON.parse(
    readFileSync(resolve(PACK_ROOT, 'manifest.json'), 'utf8')
  ) as ReleaseEvidenceManifest;
  console.log(
    `[release-evidence-pack-check] PASS: ${manifest.commands.length} commands, ` +
      `${manifest.migration.scopes.length} scope × 2 no-op rounds, source ${manifest.sourceCommit}`
  );
}

if (process.argv[1] && basename(process.argv[1]) === basename(import.meta.filename)) main();
